using System;using System.Collections.Generic;using System.Collections.ObjectModel;using System.Linq;using System.Threading;using System.Windows;using System.Windows.Controls;using System.Windows.Data;using V3SClient.libs;
namespace V3SClient.UI.Views { public sealed class EventRow_v3 { public string Time{get;set;} public string Camera{get;set;} public string Title{get;set;} public string Type{get;set;} public string Confidence{get;set;} public string AssetId{get;set;} } public partial class EventCenterPage_v3:UserControl { readonly ObservableCollection<EventRow_v3> rows=new ObservableCollection<EventRow_v3>(); readonly CancellationTokenSource cts=new CancellationTokenSource(); public EventCenterPage_v3(){InitializeComponent();EventsGrid.ItemsSource=rows;Loaded+=async(s,e)=>await RefreshAsync();Unloaded+=(s,e)=>cts.Cancel();} async System.Threading.Tasks.Task RefreshAsync(){try{var ids=(GlobalSystem.Instance.CameraList??new List<models.Camera>()).Where(c=>!string.IsNullOrWhiteSpace(c.camID)).Select(c=>c.camID.Trim()).Distinct().ToList();var now=DateTime.Now;var r=await ApiManager.Instance.GetLiveAiEventFeedAsync(now.AddDays(-1),now,ids,cts.Token);rows.Clear();foreach(var x in (r==null||r.Items==null?new List<ApiManager.LiveAiEventFeedItem>():r.Items)){DateTime t;DateTime.TryParse(x.EventTime,out t);rows.Add(new EventRow_v3{Time=t==DateTime.MinValue?x.EventTime:t.ToString("HH:mm:ss dd/MM/yyyy"),Camera=x.CameraId,Title=string.IsNullOrWhiteSpace(x.ObjectId)?x.MetaType:x.ObjectId,Type=x.EventType,Confidence=(x.Confidence*100).ToString("0.#")+"%",AssetId=x.AssetId});}CountText.Text=rows.Count+" sự kiện";}catch(Exception ex){LoggerManager.LogException(ex,"Event center refresh");}} async void Refresh_Click(object s,RoutedEventArgs e){await RefreshAsync();} void Search_TextChanged(object s,TextChangedEventArgs e){var v=CollectionViewSource.GetDefaultView(rows);var q=(SearchBox.Text??"").Trim();v.Filter=x=>string.IsNullOrWhiteSpace(q)||((EventRow_v3)x).Title.IndexOf(q,StringComparison.OrdinalIgnoreCase)>=0||((EventRow_v3)x).Camera.IndexOf(q,StringComparison.OrdinalIgnoreCase)>=0;} async void Event_Selected(object s,SelectionChangedEventArgs e){var x=EventsGrid.SelectedItem as EventRow_v3;if(x==null)return;DetailTitle.Text=x.Title;DetailText.Text=x.Camera+" · "+x.Type+" · "+x.Confidence+"\n"+x.Time;PreviewImage.Source=null;if(!string.IsNullOrWhiteSpace(x.AssetId)){var url=await ApiManager.Instance.GetAssetAccessUrlAsync(x.AssetId);if(!string.IsNullOrWhiteSpace(url))PreviewImage.Source=new System.Windows.Media.Imaging.BitmapImage(new Uri(url));}}} }
